const inputJson = $input.item.json || {};
const callbackQuery = inputJson.callback_query;
const message = inputJson.message;

let callbackData = "";
let chatId = "404755091";
let issueId = "";

if (callbackQuery) {
  callbackData = callbackQuery.data || "";
  chatId = callbackQuery.message?.chat?.id || chatId;
} else if (message) {
  chatId = message.chat?.id || chatId;
}

if (callbackData.startsWith("resolve:")) {
  issueId = callbackData.replace("resolve:", "");
} else if (callbackData.startsWith("cost:")) {
  issueId = callbackData.replace("cost:", "");
} else if (callbackData.startsWith("lang:")) {
  issueId = callbackData.replace("lang:", "");
}

return {
  json: {
    callback_data: callbackData,
    chat_id: chatId,
    issue_id: issueId,
    action: callbackData.split(":")[0] || "reply"
  }
};
